ALTER TABLE public.employees ADD COLUMN IF NOT EXISTS nine_box_override text;
ALTER TABLE public.employees ADD COLUMN IF NOT EXISTS new_joiner_exp_feedback numeric;
ALTER TABLE public.employees ADD COLUMN IF NOT EXISTS new_joiner_mgr_feedback numeric;
ALTER TABLE public.employees ADD COLUMN IF NOT EXISTS new_joiner_risk_score numeric;

CREATE TABLE IF NOT EXISTS public.hrbp_scopes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_email text NOT NULL,
  department text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(user_email, department)
);
GRANT SELECT ON public.hrbp_scopes TO authenticated;
GRANT ALL ON public.hrbp_scopes TO service_role;
ALTER TABLE public.hrbp_scopes ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Anyone can read scopes" ON public.hrbp_scopes;
CREATE POLICY "Anyone can read scopes" ON public.hrbp_scopes FOR SELECT TO authenticated USING (true);
DROP POLICY IF EXISTS "Admins manage scopes" ON public.hrbp_scopes;
CREATE POLICY "Admins manage scopes" ON public.hrbp_scopes FOR ALL TO authenticated
  USING (public.has_role(auth.uid(),'hrbp_admin')) WITH CHECK (public.has_role(auth.uid(),'hrbp_admin'));

