  ('tanvi@flick2know.com','Customer Success')
ON CONFLICT (user_email, department) DO NOTHING;

CREATE OR REPLACE FUNCTION public.is_scoped_hrbp(_email text, _department text)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.hrbp_scopes
    WHERE lower(user_email)=lower(coalesce(_email,''))
      AND department = _department
  )
$$;
GRANT EXECUTE ON FUNCTION public.is_scoped_hrbp(text,text) TO authenticated;

DROP POLICY IF EXISTS "Employees readable by allowed viewers" ON public.employees;
DROP POLICY IF EXISTS "View employees by role/hierarchy" ON public.employees;
CREATE POLICY "Employees readable by allowed viewers" ON public.employees
FOR SELECT TO authenticated
USING (
  public.has_role(auth.uid(),'hrbp_admin')
  OR public.is_scoped_hrbp(public.current_user_email(), department)
  OR public.can_view_emp_v2(public.current_user_email(), emp_id, manager_email, rollup_manager_email, function_head_email, email)
);

CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE
  _email text := lower(NEW.email);
  _role app_role;
BEGIN
  INSERT INTO public.profiles (id, email, full_name)
  VALUES (NEW.id, NEW.email, COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.email))
  ON CONFLICT (id) DO NOTHING;

  IF _email IN ('pranay.kumar@flick2know.com','sumiti@flick2know.com') THEN
    _role := 'hrbp_admin';
  ELSIF EXISTS (SELECT 1 FROM public.employees WHERE lower(function_head_email)=_email) THEN
    _role := 'function_head';
  ELSIF EXISTS (SELECT 1 FROM public.employees WHERE lower(rollup_manager_email)=_email) THEN
    _role := 'rollup_manager';
  ELSE
    _role := 'manager';
  END IF;
  INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, _role) ON CONFLICT DO NOTHING;
  RETURN NEW;
END $$;

INSERT INTO public.user_roles(user_id, role)
SELECT p.id, 'hrbp_admin'::app_role FROM public.profiles p
WHERE lower(p.email) = 'sumiti@flick2know.com'
ON CONFLICT (user_id, role) DO NOTHING;